/* prog26_wildcard_match – reproduced behaviour of the original binary
 *
 * Usage:
 *   prog26_wildcard_match <pattern> <text>
 *
 * The pattern may contain the wild‑cards '*' (any sequence, possibly empty)
 * and '?' (any single character).  If the pattern matches the text the program
 * prints "MATCH", otherwise "NO_MATCH".  If the arguments are missing or any
 * argument is longer than 64 characters the program prints "USAGE".
 */

#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 64   /* original binary accepts lengths < 0x41 (65) */

int main(int argc, char *argv[])
{
    /* Accept at least two arguments after the program name; extra arguments are ignored */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);

    if (plen > MAXLEN || tlen > MAXLEN) {
        puts("USAGE");
        return 0;
    }

    /* dp[i][j] – does pattern[0..i-1] match text[0..j-1] ? */
    bool dp[MAXLEN + 1][MAXLEN + 1] = { false };

    dp[0][0] = true;                     /* empty pattern matches empty text */

    /* pattern prefixes against empty text */
    for (size_t i = 1; i <= plen; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }

    /* fill the table */
    for (size_t i = 1; i <= plen; ++i) {
        for (size_t j = 1; j <= tlen; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*')
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            else if (pc == '?' || pc == tc)
                dp[i][j] = dp[i - 1][j - 1];
            else
                dp[i][j] = false;
        }
    }

    puts(dp[plen][tlen] ? "MATCH" : "NO_MATCH");
    return 0;
}
